def _translate_dynamic_forecast(text, lang):
    """Translate the generated seven-day forecast sentence while preserving values."""
    import re
    m = re.match(r"Forecast for the next (\d+) days: highs ([\d.]+) to ([\d.]+)°C, total rain ([\d.]+) mm(?:, wettest day (\d{4}-\d{2}-\d{2}) \(([\d.]+) mm\))?\.?", text)
    if not m:
        return None
    days, low, high, rain, wet_day, wet_mm = m.groups()
    if lang == "te":
        out = f"తదుపరి {days} రోజుల వాతావరణ సూచన: గరిష్ఠ ఉష్ణోగ్రతలు {low} నుండి {high}°C వరకు, మొత్తం వర్షపాతం {rain} మి.మీ."
        if wet_day: out += f", అత్యధిక వర్షం {wet_day}న ({wet_mm} మి.మీ.)"
        return out + "."
    if lang == "hi":
        out = f"अगले {days} दिनों का पूर्वानुमान: अधिकतम तापमान {low} से {high}°C, कुल वर्षा {rain} मिमी"
        if wet_day: out += f", सबसे अधिक वर्षा {wet_day} को ({wet_mm} मिमी)"
        return out + "।"
    if lang == "kn":
        out = f"ಮುಂದಿನ {days} ದಿನಗಳ ಮುನ್ಸೂಚನೆ: ಗರಿಷ್ಠ ತಾಪಮಾನ {low} ರಿಂದ {high}°C, ಒಟ್ಟು ಮಳೆ {rain} ಮಿ.ಮೀ."
        if wet_day: out += f", ಅತಿ ಹೆಚ್ಚು ಮಳೆ {wet_day} ರಂದು ({wet_mm} ಮಿ.ಮೀ.)"
        return out + "."
    return None


def _translate_dynamic_hi_kn(text, lang):
    """Translate common numeric advice templates in Hindi and Kannada."""
    import re
    if lang not in ("hi", "kn"):
        return None
    hi = lang == "hi"
    # v7.3: numeric explanations in the irrigation "Why?" card.
    m = re.match(r"(Sandy|Red|Loamy|Clay|Black) soil holds about ([\d.]+) mm of usable water in the root zone \(([\d.]+) m deep\); roughly ([\d.]+) mm is already used\.?", text)
    if m:
        soil_en, capacity, depth, used = m.groups()
        if hi:
            soil = {"Sandy":"रेतीली मिट्टी","Red":"लाल मिट्टी","Loamy":"दोमट मिट्टी","Clay":"चिकनी मिट्टी","Black":"काली मिट्टी"}[soil_en]
            return f"{soil} जड़ों के क्षेत्र में लगभग {capacity} मिमी उपयोगी पानी रोकती है (जड़ों की गहराई {depth} मीटर); इसमें से लगभग {used} मिमी पानी पहले ही उपयोग हो चुका है।"
        soil = {"Sandy":"ಮರಳು ಮಣ್ಣು","Red":"ಕೆಂಪು ಮಣ್ಣು","Loamy":"ಗೋಡು ಮಣ್ಣು","Clay":"ಜೇಡಿ ಮಣ್ಣು","Black":"ಕಪ್ಪು ಮಣ್ಣು"}[soil_en]
        return f"{soil} ಬೇರು ವಲಯದಲ್ಲಿ ಸುಮಾರು {capacity} ಮಿ.ಮೀ. ಬಳಸಬಹುದಾದ ನೀರನ್ನು ಹಿಡಿದಿಡುತ್ತದೆ (ಬೇರಿನ ಆಳ {depth} ಮೀಟರ್); ಇದರಲ್ಲಿ ಸುಮಾರು {used} ಮಿ.ಮೀ. ಈಗಾಗಲೇ ಬಳಕೆಯಾಗಿದೆ."
    m = re.match(r"Stress starts once ([\d.]+) mm is used up, so that is the trigger level\.?", text)
    if m:
        return (f"{m.group(1)} मिमी पानी उपयोग हो जाने पर फसल पर जल-तनाव शुरू होता है। यही सिंचाई शुरू करने का स्तर है।" if hi else f"{m.group(1)} ಮಿ.ಮೀ. ನೀರು ಬಳಕೆಯಾದಾಗ ಬೆಳೆಗೆ ನೀರಿನ ಒತ್ತಡ ಆರಂಭವಾಗುತ್ತದೆ. ಇದೇ ನೀರಾವರಿ ಆರಂಭಿಸುವ ಮಿತಿ.")
    m = re.match(r"(.+?) at the (.+?) stage has crop factor Kc ([\d.]+); with ET₀ ([\d.]+) mm/day it uses about ([\d.]+) mm/day\.?", text)
    if m:
        crop, stage, kc, et0, use = m.groups()
        stage_hi = {"initial":"शुरुआती", "development":"विकास", "mid-season":"मध्य", "late-season":"अंतिम"}.get(stage.lower(), stage)
        stage_kn = {"initial":"ಆರಂಭಿಕ", "development":"ಬೆಳವಣಿಗೆ", "mid-season":"ಮಧ್ಯಮ", "late-season":"ಕೊನೆಯ"}.get(stage.lower(), stage)
        crop_hi = {"Tomato":"टमाटर", "Rice":"धान", "Wheat":"गेहूँ", "Maize":"मक्का", "Sugarcane":"गन्ना", "Cotton":"कपास", "Groundnut":"मूँगफली", "Millet":"बाजरा"}.get(crop, crop)
        crop_kn = {"Tomato":"ಟೊಮೆಟೊ", "Rice":"ಭತ್ತ", "Wheat":"ಗೋಧಿ", "Maize":"ಮೆಕ್ಕೆಜೋಳ", "Sugarcane":"ಕಬ್ಬು", "Cotton":"ಹತ್ತಿ", "Groundnut":"ಕಡಲೆಕಾಯಿ", "Millet":"ಸಿರಿಧಾನ್ಯ"}.get(crop, crop)
        return (f"{crop_hi} की {stage_hi} अवस्था में फसल गुणांक Kc {kc} है। ET₀ {et0} मिमी/दिन होने पर यह प्रतिदिन लगभग {use} मिमी पानी उपयोग करती है।" if hi else f"{stage_kn} ಹಂತದಲ್ಲಿರುವ {crop_kn} ಬೆಳೆಯ Kc ಗುಣಕ {kc}. ET₀ ದಿನಕ್ಕೆ {et0} ಮಿ.ಮೀ. ಇದ್ದಾಗ ಇದು ದಿನಕ್ಕೆ ಸುಮಾರು {use} ಮಿ.ಮೀ. ನೀರನ್ನು ಬಳಸುತ್ತದೆ.")
    m = re.match(r"Forecast rain over 7 days: ([\d.]+) mm \(only ([\d.]+) mm counted as useful\)\.?", text)
    if m:
        total, useful = m.groups()
        return (f"अगले 7 दिनों में अनुमानित वर्षा: {total} मिमी (इसमें से केवल {useful} मिमी को उपयोगी वर्षा माना गया है)।" if hi else f"ಮುಂದಿನ 7 ದಿನಗಳ ಮಳೆ ಮುನ್ಸೂಚನೆ: {total} ಮಿ.ಮೀ. (ಇದರಲ್ಲಿ {useful} ಮಿ.ಮೀ. ಮಾತ್ರ ಉಪಯುಕ್ತ ಮಳೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗಿದೆ).")
    m = re.match(r"Apply about ([\d,.]+) mm \(about ([\d,.]+) litres per acre\) to refill the root zone\.?", text)
    if m:
        return (f"जड़ों के क्षेत्र में नमी लौटाने के लिए लगभग {m.group(1)} मिमी पानी (प्रति एकड़ लगभग {m.group(2)} लीटर) दें।" if hi else f"ಬೇರು ವಲಯದ ತೇವಾಂಶ ತುಂಬಲು ಸುಮಾರು {m.group(1)} ಮಿ.ಮೀ. ನೀರು (ಪ್ರತಿ ಎಕರೆಗೆ ಸುಮಾರು {m.group(2)} ಲೀಟರ್) ನೀಡಿ.")
    m = re.match(r"Soil will hit the stress limit by tonight\. Plan about ([\d,.]+) mm\.?", text)
    if m:
        return (f"आज रात तक मिट्टी की नमी तनाव सीमा तक पहुँच सकती है। लगभग {m.group(1)} मिमी पानी की योजना बनाएँ।" if hi else f"ಇಂದು ರಾತ್ರಿ ವೇಳೆಗೆ ಮಣ್ಣಿನ ತೇವಾಂಶ ಒತ್ತಡದ ಮಿತಿಗೆ ತಲುಪಬಹುದು. ಸುಮಾರು {m.group(1)} ಮಿ.ಮೀ. ನೀರಿಗೆ ಯೋಜನೆ ಮಾಡಿ.")
    m = re.match(r"Soil is getting dry but about ([\d,.]+) mm of rain is likely today\. Re-check tomorrow\.?", text)
    if m:
        return (f"मिट्टी सूख रही है, लेकिन आज लगभग {m.group(1)} मिमी बारिश की संभावना है। कल फिर जाँचें।" if hi else f"ಮಣ್ಣು ಒಣಗುತ್ತಿದೆ, ಆದರೆ ಇಂದು ಸುಮಾರು {m.group(1)} ಮಿ.ಮೀ. ಮಳೆಯ ಸಾಧ್ಯತೆ ಇದೆ. ನಾಳೆ ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ.")
    m = re.match(r"Irrigate in (\d+) day\(s\)\.?", text)
    if m:
        return (f"{m.group(1)} दिन में सिंचाई करें।" if hi else f"{m.group(1)} ದಿನಗಳಲ್ಲಿ ನೀರಾವರಿ ಮಾಡಿ.")
    m = re.match(r"Irrigation: (.+?)\. (.+)", text)
    if m:
        a = translate_advice_text(m.group(1), lang)
        b = translate_advice_text(m.group(2), lang)
        return (f"सिंचाई: {a}। {b}" if hi else f"ನೀರಾವರಿ: {a}. {b}")
    m = re.match(r"Hot day \(([\d.]+)°C\): irrigate early morning or evening, avoid midday field work\.?", text)
    if m:
        return (f"गर्म दिन ({m.group(1)}°C): सुबह जल्दी या शाम को सिंचाई करें; दोपहर में खेत का काम न करें।" if hi else f"ಬಿಸಿ ದಿನ ({m.group(1)}°C): ಮುಂಜಾನೆ ಅಥವಾ ಸಂಜೆ ನೀರಾವರಿ ಮಾಡಿ; ಮಧ್ಯಾಹ್ನ ಹೊಲದ ಕೆಲಸ ತಪ್ಪಿಸಿ.")
    m = re.match(r"Heavy rain \(([\d.]+) mm\) expected: clear drains(?:; harvest early if the crop is ready)?\.?", text)
    if m:
        return (f"भारी बारिश ({m.group(1)} मिमी) की संभावना है: जल निकासी नालियाँ साफ करें। फसल तैयार हो तो जल्दी कटाई करें।" if hi else f"ಭಾರಿ ಮಳೆ ({m.group(1)} ಮಿ.ಮೀ.) ನಿರೀಕ್ಷಿಸಲಾಗಿದೆ: ನೀರು ಹರಿಯುವ ಕಾಲುವೆಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ. ಬೆಳೆ ಸಿದ್ಧವಾಗಿದ್ದರೆ ಬೇಗ ಕೊಯ್ಲು ಮಾಡಿ.")
    m = re.match(r"Stage task: (.+)", text)
    if m:
        task = translate_advice_text(m.group(1), lang)
        return (f"इस अवस्था में करने का काम: {task}" if hi else f"ಈ ಹಂತದಲ್ಲಿ ಮಾಡಬೇಕಾದ ಕೆಲಸ: {task}")
    m = re.match(r"Great match: (.+?) is the best fit for your soil and climate\.?", text)
    if m:
        return (f"बहुत अच्छा मेल: {m.group(1)} आपकी मिट्टी और जलवायु के लिए सबसे उपयुक्त है।" if hi else f"ಉತ್ತಮ ಹೊಂದಾಣಿಕೆ: {m.group(1)} ನಿಮ್ಮ ಮಣ್ಣು ಮತ್ತು ಹವಾಮಾನಕ್ಕೆ ಅತ್ಯಂತ ಸೂಕ್ತವಾಗಿದೆ.")
    m = re.match(r"Reasonable match for (.+?), but (.+?) fits slightly better\.?", text)
    if m:
        return (f"{m.group(1)} का मेल ठीक है, लेकिन {m.group(2)} थोड़ा अधिक उपयुक्त है।" if hi else f"{m.group(1)} ಹೊಂದಾಣಿಕೆ ಸಮಂಜಸವಾಗಿದೆ, ಆದರೆ {m.group(2)} ಸ್ವಲ್ಪ ಹೆಚ್ಚು ಸೂಕ್ತವಾಗಿದೆ.")
    m = re.match(r"Weak match for (.+?)\. Your soil and climate suit (.+?) much better\.?", text)
    if m:
        return (f"{m.group(1)} का मेल कमजोर है। आपकी मिट्टी और जलवायु के लिए {m.group(2)} अधिक उपयुक्त है।" if hi else f"{m.group(1)} ಹೊಂದಾಣಿಕೆ ಕಡಿಮೆ. ನಿಮ್ಮ ಮಣ್ಣು ಮತ್ತು ಹವಾಮಾನಕ್ಕೆ {m.group(2)} ಹೆಚ್ಚು ಸೂಕ್ತವಾಗಿದೆ.")
    m = re.match(r"Basal \(at sowing\): all DAP and MOP, plus 1/3 of urea \(about ([\d.]+) kg/acre\)\.?", text)
    if m:
        return (f"बुवाई के समय: पूरी DAP और MOP मात्रा तथा यूरिया का 1/3 भाग (लगभग {m.group(1)} किग्रा/एकड़) डालें।" if hi else f"ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ: ಪೂರ್ಣ DAP ಮತ್ತು MOP ಜೊತೆಗೆ ಯೂರಿಯಾದ 1/3 ಭಾಗ (ಸುಮಾರು {m.group(1)} ಕೆ.ಜಿ./ಎಕರೆ) ಹಾಕಿ.")
    m = re.match(r"First top-dressing: 1/3 of urea around the (.+?) stage\.?", text)
    if m:
        return (f"ಮೊದಲ ಮೇಲ್ಗೊಬ್ಬರ: {m.group(1)} ಹಂತದ ಸಮಯದಲ್ಲಿ ಯೂರಿಯಾದ 1/3 ಭಾಗ ಹಾಕಿ." if not hi else f"पहली टॉप-ड्रेसिंग: {m.group(1)} अवस्था के आसपास यूरिया का 1/3 भाग डालें।")
    if text.startswith("Second top-dressing: last 1/3 of urea near flowering"):
        return ("दूसरी टॉप-ड्रेसिंग: फूल आने के समय यूरिया का अंतिम 1/3 भाग डालें। भारी बारिश की संभावना हो तो इसे रोकें।" if hi else "ಎರಡನೇ ಮೇಲ್ಗೊಬ್ಬರ: ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಉಳಿದ 1/3 ಯೂರಿಯಾ ಹಾಕಿ. ಭಾರಿ ಮಳೆಯ ಮುನ್ಸೂಚನೆ ಇದ್ದರೆ ಹಾಕಬೇಡಿ.")
    m = re.match(r"Forecast rain over 7 days: ([\d.]+) mm \(only ([\d.]+) mm counted as useful\)\.?", text)
    if m:
        return (f"7 दिनों में अनुमानित वर्षा: {m.group(1)} मिमी (इसमें से केवल {m.group(2)} मिमी उपयोगी वर्षा मानी गई है)।" if hi else f"7 ದಿನಗಳ ಮಳೆ ಮುನ್ಸೂಚನೆ: {m.group(1)} ಮಿ.ಮೀ. (ಇದರಲ್ಲಿ {m.group(2)} ಮಿ.ಮೀ. ಮಾತ್ರ ಉಪಯುಕ್ತ ಮಳೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗಿದೆ).")
    return None


# v7.3: complete fixed phrase coverage for farmer-facing generated advice.
for _lang, _phrases in {'hi': {'Seedlings are shallow-rooted: give light, frequent water and protect from heat.': 'पौधों की जड़ें उथली होती हैं। थोड़ी-थोड़ी मात्रा में बार-बार पानी दें और उन्हें गर्मी से बचाएँ।', 'Water at the base and avoid wetting leaves to reduce blight risk.': 'पत्तियों को गीला किए बिना पौधे की जड़ के पास पानी दें। इससे झुलसा रोग का खतरा कम होगा।', 'Roots are growing: keep soil evenly moist and apply the first fertilizer dose as advised locally.': 'जड़ें बढ़ रही हैं। मिट्टी में समान नमी बनाए रखें और स्थानीय सलाह के अनुसार खाद की पहली मात्रा दें।', 'Peak water demand: avoid any moisture stress now, it hurts yield the most.': 'इस अवस्था में पानी की आवश्यकता सबसे अधिक होती है। नमी की कमी न होने दें, क्योंकि इससे उपज पर सबसे अधिक असर पड़ता है।', 'Water need is falling: reduce irrigation gradually and plan harvest around dry weather.': 'अब पानी की आवश्यकता कम हो रही है। सिंचाई धीरे-धीरे कम करें और शुष्क मौसम में कटाई की योजना बनाएँ।', 'Paddy is usually kept flooded; treat the amount shown as the top-up needed.': 'धान के खेत में सामान्यतः पानी भरा रखा जाता है। दिखाई गई मात्रा को अतिरिक्त पानी की आवश्यकता मानें।', 'Excess water at flowering causes boll drop; avoid waterlogging.': 'फूल आने की अवस्था में अधिक पानी से फल/डोडे गिर सकते हैं। खेत में पानी जमा न होने दें।', 'Heavy feeder of water; mulch trash to cut evaporation.': 'इस फसल को अधिक पानी चाहिए। वाष्पीकरण कम करने के लिए फसल के अवशेषों से मल्चिंग करें।', 'Crown-root and flowering stages are most sensitive to dry soil.': 'क्राउन-रूट और फूल आने की अवस्थाएँ सूखी मिट्टी के प्रति सबसे अधिक संवेदनशील होती हैं।', 'Red soil is low in organic matter: add compost or FYM and apply phosphorus near the roots.': 'लाल मिट्टी में जैविक पदार्थ कम होता है। कम्पोस्ट या गोबर की खाद डालें और जड़ों के पास फॉस्फोरस दें।', 'Sandy soil leaches nutrients: split nitrogen into 3-4 smaller doses and use mulch or compost to hold water.': 'रेतीली मिट्टी में पोषक तत्व जल्दी बह जाते हैं। नाइट्रोजन को 3–4 छोटी खुराकों में दें और नमी बनाए रखने के लिए मल्च या कम्पोस्ट का उपयोग करें।', 'Loamy soil holds water and nutrients well: standard split doses work.': 'दोमट मिट्टी पानी और पोषक तत्व अच्छी तरह रोकती है। सामान्य विभाजित खुराकें उपयोग की जा सकती हैं।', 'Clay soil drains slowly: avoid waterlogging, make drainage channels and avoid working it when wet.': 'चिकनी मिट्टी से पानी धीरे निकलता है। जलभराव से बचें, निकासी नालियाँ बनाएँ और गीली मिट्टी में खेत का काम न करें।', 'Black soil cracks when dry and sticks when wet: apply P and K as basal dose and avoid field work in wet spells.': 'काली मिट्टी सूखने पर फटती है और गीली होने पर चिपकती है। फॉस्फोरस और पोटाश की आधार खुराक दें तथा अधिक गीलापन होने पर खेत में काम न करें।', 'Guideline only. Confirm doses with your local agriculture office.': 'यह केवल सामान्य मार्गदर्शन है। खाद की मात्रा स्थानीय कृषि कार्यालय से अवश्य पुष्टि करें।', 'Best dry, calm day for spraying and fertilizer top-dressing.': 'छिड़काव और ऊपर से खाद डालने के लिए यह सबसे अच्छा सूखा और कम हवा वाला दिन है।', 'No dry, calm day in the forecast: hold off spraying and fertilizer.': 'पूर्वानुमान में कोई सूखा और कम हवा वाला दिन नहीं है। छिड़काव और खाद डालना फिलहाल टालें।', 'Prepare the land, buy certified seed and sow on the first dry day once soil moisture is adequate.': 'खेत तैयार करें, प्रमाणित बीज खरीदें और मिट्टी में पर्याप्त नमी होने पर पहले सूखे दिन बुवाई करें।'}, 'kn': {'Seedlings are shallow-rooted: give light, frequent water and protect from heat.': 'ಸಸಿಗಳ ಬೇರುಗಳು ಆಳವಾಗಿರುವುದಿಲ್ಲ. ಕಡಿಮೆ ಪ್ರಮಾಣದಲ್ಲಿ ಆಗಾಗ್ಗೆ ನೀರು ಹಾಕಿ ಮತ್ತು ಬಿಸಿಲಿನಿಂದ ರಕ್ಷಿಸಿ.', 'Water at the base and avoid wetting leaves to reduce blight risk.': 'ಎಲೆಗಳನ್ನು ತೇವಗೊಳಿಸದೆ ಗಿಡದ ಬುಡಕ್ಕೆ ನೀರು ಹಾಕಿ. ಇದರಿಂದ ಅಂಗಮಾರಿ ರೋಗದ ಅಪಾಯ ಕಡಿಮೆಯಾಗುತ್ತದೆ.', 'Roots are growing: keep soil evenly moist and apply the first fertilizer dose as advised locally.': 'ಬೇರುಗಳು ಬೆಳೆಯುತ್ತಿವೆ. ಮಣ್ಣಿನಲ್ಲಿ ಸಮತಟ್ಟಾದ ತೇವಾಂಶ ಕಾಪಾಡಿ ಮತ್ತು ಸ್ಥಳೀಯ ಸಲಹೆಯಂತೆ ಮೊದಲ ಗೊಬ್ಬರದ ಪ್ರಮಾಣ ಹಾಕಿ.', 'Peak water demand: avoid any moisture stress now, it hurts yield the most.': 'ಈ ಹಂತದಲ್ಲಿ ನೀರಿನ ಅವಶ್ಯಕತೆ ಅತ್ಯಧಿಕವಾಗಿರುತ್ತದೆ. ತೇವಾಂಶದ ಕೊರತೆಯಾಗದಂತೆ ನೋಡಿಕೊಳ್ಳಿ; ಇದು ಇಳುವರಿಯನ್ನು ಹೆಚ್ಚು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.', 'Water need is falling: reduce irrigation gradually and plan harvest around dry weather.': 'ಈಗ ನೀರಿನ ಅವಶ್ಯಕತೆ ಕಡಿಮೆಯಾಗುತ್ತಿದೆ. ನೀರಾವರಿಯನ್ನು ನಿಧಾನವಾಗಿ ಕಡಿಮೆ ಮಾಡಿ ಮತ್ತು ಒಣ ಹವಾಮಾನದಲ್ಲಿ ಕೊಯ್ಲು ಯೋಜಿಸಿ.', 'Paddy is usually kept flooded; treat the amount shown as the top-up needed.': 'ಭತ್ತದ ಗದ್ದೆಯಲ್ಲಿ ಸಾಮಾನ್ಯವಾಗಿ ನೀರು ನಿಲ್ಲಿಸಲಾಗುತ್ತದೆ. ತೋರಿಸಿರುವ ಪ್ರಮಾಣವನ್ನು ಹೆಚ್ಚುವರಿಯಾಗಿ ಬೇಕಾದ ನೀರೆಂದು ಪರಿಗಣಿಸಿ.', 'Excess water at flowering causes boll drop; avoid waterlogging.': 'ಹೂ ಬಿಡುವ ಹಂತದಲ್ಲಿ ಹೆಚ್ಚು ನೀರು ಕಾಯಿಗಳು ಉದುರುವಂತೆ ಮಾಡಬಹುದು. ಹೊಲದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಿ.', 'Heavy feeder of water; mulch trash to cut evaporation.': 'ಈ ಬೆಳೆಗೆ ಹೆಚ್ಚು ನೀರು ಬೇಕಾಗುತ್ತದೆ. ಆವಿಯಾಗುವಿಕೆ ಕಡಿಮೆ ಮಾಡಲು ಬೆಳೆ ಅವಶೇಷಗಳಿಂದ ಮಲ್ಚಿಂಗ್ ಮಾಡಿ.', 'Crown-root and flowering stages are most sensitive to dry soil.': 'ಕಿರೀಟ ಬೇರು ಮತ್ತು ಹೂ ಬಿಡುವ ಹಂತಗಳು ಒಣ ಮಣ್ಣಿಗೆ ಹೆಚ್ಚು ಸೂಕ್ಷ್ಮವಾಗಿವೆ.', 'Red soil is low in organic matter: add compost or FYM and apply phosphorus near the roots.': 'ಕೆಂಪು ಮಣ್ಣಿನಲ್ಲಿ ಸಾವಯವ ಪದಾರ್ಥ ಕಡಿಮೆ ಇರುತ್ತದೆ. ಕಾಂಪೋಸ್ಟ್ ಅಥವಾ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಸೇರಿಸಿ ಮತ್ತು ಬೇರುಗಳ ಬಳಿ ರಂಜಕ ಹಾಕಿ.', 'Sandy soil leaches nutrients: split nitrogen into 3-4 smaller doses and use mulch or compost to hold water.': 'ಮರಳು ಮಣ್ಣಿನಲ್ಲಿ ಪೋಷಕಾಂಶಗಳು ಬೇಗ ತೊಳೆದು ಹೋಗುತ್ತವೆ. ಸಾರಜನಕವನ್ನು 3–4 ಸಣ್ಣ ಪ್ರಮಾಣಗಳಲ್ಲಿ ನೀಡಿ ಮತ್ತು ತೇವಾಂಶ ಉಳಿಸಲು ಮಲ್ಚ್ ಅಥವಾ ಕಾಂಪೋಸ್ಟ್ ಬಳಸಿ.', 'Loamy soil holds water and nutrients well: standard split doses work.': 'ಗೋಡು ಮಣ್ಣು ನೀರು ಮತ್ತು ಪೋಷಕಾಂಶಗಳನ್ನು ಚೆನ್ನಾಗಿ ಹಿಡಿದಿಡುತ್ತದೆ. ಸಾಮಾನ್ಯ ವಿಭಜಿತ ಗೊಬ್ಬರ ಪ್ರಮಾಣಗಳನ್ನು ಬಳಸಬಹುದು.', 'Clay soil drains slowly: avoid waterlogging, make drainage channels and avoid working it when wet.': 'ಜೇಡಿ ಮಣ್ಣಿನಲ್ಲಿ ನೀರು ನಿಧಾನವಾಗಿ ಹರಿಯುತ್ತದೆ. ನೀರು ನಿಲ್ಲದಂತೆ ಕಾಲುವೆ ಮಾಡಿ ಮತ್ತು ಮಣ್ಣು ಒದ್ದೆಯಾಗಿರುವಾಗ ಹೊಲದ ಕೆಲಸ ಮಾಡಬೇಡಿ.', 'Black soil cracks when dry and sticks when wet: apply P and K as basal dose and avoid field work in wet spells.': 'ಕಪ್ಪು ಮಣ್ಣು ಒಣಗಿದಾಗ ಬಿರುಕು ಬಿಡುತ್ತದೆ ಮತ್ತು ಒದ್ದೆಯಾದಾಗ ಅಂಟುತ್ತದೆ. ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಶ್ ಅನ್ನು ಮೂಲ ಗೊಬ್ಬರವಾಗಿ ಹಾಕಿ; ಮಳೆಗಾಲದಲ್ಲಿ ಹೊಲದ ಕೆಲಸ ತಪ್ಪಿಸಿ.', 'Guideline only. Confirm doses with your local agriculture office.': 'ಇದು ಸಾಮಾನ್ಯ ಮಾರ್ಗದರ್ಶನ ಮಾತ್ರ. ಗೊಬ್ಬರದ ಪ್ರಮಾಣವನ್ನು ಸ್ಥಳೀಯ ಕೃಷಿ ಕಚೇರಿಯಲ್ಲಿ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.', 'Best dry, calm day for spraying and fertilizer top-dressing.': 'ಸಿಂಪಡಣೆ ಮತ್ತು ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಲು ಇದು ಉತ್ತಮವಾದ ಒಣ ಹಾಗೂ ಗಾಳಿ ಕಡಿಮೆ ಇರುವ ದಿನ.', 'No dry, calm day in the forecast: hold off spraying and fertilizer.': 'ಮುನ್ಸೂಚನೆಯಲ್ಲಿ ಒಣ ಮತ್ತು ಗಾಳಿ ಕಡಿಮೆ ಇರುವ ದಿನವಿಲ್ಲ. ಸಿಂಪಡಣೆ ಮತ್ತು ಗೊಬ್ಬರ ಹಾಕುವುದನ್ನು ಮುಂದೂಡಿ.', 'Prepare the land, buy certified seed and sow on the first dry day once soil moisture is adequate.': 'ಭೂಮಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಿ, ಪ್ರಮಾಣಿತ ಬೀಜ ಖರೀದಿಸಿ ಮತ್ತು ಮಣ್ಣಿನಲ್ಲಿ ಸಾಕಷ್ಟು ತೇವವಿರುವ ಮೊದಲ ಒಣ ದಿನ ಬಿತ್ತನೆ ಮಾಡಿ.'}}.items():
    ADVICE_PHRASES.setdefault(_lang, {}).update(_phrases)

# v7.4: extend generated-advice phrase coverage in every supported language.
for _lang, _items in {'hi': {'Seedlings are shallow-rooted: give light, frequent water and protect from heat.': 'पौधों की जड़ें उथली होती हैं। थोड़ी-थोड़ी मात्रा में बार-बार पानी दें और उन्हें गर्मी से बचाएँ।', 'Water at the base and avoid wetting leaves to reduce blight risk.': 'पत्तियों को गीला किए बिना पौधे की जड़ के पास पानी दें। इससे झुलसा रोग का खतरा कम होगा।', 'Roots are growing: keep soil evenly moist and apply the first fertilizer dose as advised locally.': 'जड़ें बढ़ रही हैं। मिट्टी में समान नमी बनाए रखें और स्थानीय सलाह के अनुसार खाद की पहली मात्रा दें।', 'Peak water demand: avoid any moisture stress now, it hurts yield the most.': 'इस अवस्था में पानी की आवश्यकता सबसे अधिक होती है। नमी की कमी न होने दें, क्योंकि इससे उपज पर सबसे अधिक असर पड़ता है।', 'Water need is falling: reduce irrigation gradually and plan harvest around dry weather.': 'अब पानी की आवश्यकता कम हो रही है। सिंचाई धीरे-धीरे कम करें और शुष्क मौसम में कटाई की योजना बनाएँ।', 'Paddy is usually kept flooded; treat the amount shown as the top-up needed.': 'धान के खेत में सामान्यतः पानी भरा रखा जाता है। दिखाई गई मात्रा को अतिरिक्त पानी की आवश्यकता मानें।', 'Excess water at flowering causes boll drop; avoid waterlogging.': 'फूल आने की अवस्था में अधिक पानी से फल/डोडे गिर सकते हैं। खेत में पानी जमा न होने दें।', 'Heavy feeder of water; mulch trash to cut evaporation.': 'इस फसल को अधिक पानी चाहिए। वाष्पीकरण कम करने के लिए फसल के अवशेषों से मल्चिंग करें।', 'Crown-root and flowering stages are most sensitive to dry soil.': 'क्राउन-रूट और फूल आने की अवस्थाएँ सूखी मिट्टी के प्रति सबसे अधिक संवेदनशील होती हैं।', 'Red soil is low in organic matter: add compost or FYM and apply phosphorus near the roots.': 'लाल मिट्टी में जैविक पदार्थ कम होता है। कम्पोस्ट या गोबर की खाद डालें और जड़ों के पास फॉस्फोरस दें।', 'Sandy soil leaches nutrients: split nitrogen into 3-4 smaller doses and use mulch or compost to hold water.': 'रेतीली मिट्टी में पोषक तत्व जल्दी बह जाते हैं। नाइट्रोजन को 3–4 छोटी खुराकों में दें और नमी बनाए रखने के लिए मल्च या कम्पोस्ट का उपयोग करें।', 'Loamy soil holds water and nutrients well: standard split doses work.': 'दोमट मिट्टी पानी और पोषक तत्व अच्छी तरह रोकती है। सामान्य विभाजित खुराकें उपयोग की जा सकती हैं।', 'Clay soil drains slowly: avoid waterlogging, make drainage channels and avoid working it when wet.': 'चिकनी मिट्टी से पानी धीरे निकलता है। जलभराव से बचें, निकासी नालियाँ बनाएँ और गीली मिट्टी में खेत का काम न करें।', 'Black soil cracks when dry and sticks when wet: apply P and K as basal dose and avoid field work in wet spells.': 'काली मिट्टी सूखने पर फटती है और गीली होने पर चिपकती है। फॉस्फोरस और पोटाश की आधार खुराक दें तथा अधिक गीलापन होने पर खेत में काम न करें।', 'Your crop match': 'आपकी फसल की अनुकूलता', 'average temperature': 'औसत तापमान', 'AI picked': 'AI द्वारा चुना गया', 'Prices, yields and fit scores are sample values. Check with your local market and agriculture office.': 'कीमतें, उपज और अनुकूलता अंक नमूना मान हैं। स्थानीय बाजार और कृषि कार्यालय से पुष्टि करें।', 'Yield, cost and price are sample defaults. Update them from MSP, Agmarknet or local data.': 'उपज, लागत और कीमतें नमूना मान हैं। इन्हें MSP, Agmarknet या स्थानीय जानकारी से अपडेट करें।', 'Rice': 'चावल', 'Wheat': 'गेहूँ', 'Maize': 'मक्का', 'Tomato': 'टमाटर', 'Cotton': 'कपास', 'Sugarcane': 'गन्ना', 'Ragi': 'रागी'}, 'kn': {'Seedlings are shallow-rooted: give light, frequent water and protect from heat.': 'ಸಸಿಗಳ ಬೇರುಗಳು ಆಳವಾಗಿರುವುದಿಲ್ಲ. ಕಡಿಮೆ ಪ್ರಮಾಣದಲ್ಲಿ ಆಗಾಗ್ಗೆ ನೀರು ಹಾಕಿ ಮತ್ತು ಬಿಸಿಲಿನಿಂದ ರಕ್ಷಿಸಿ.', 'Water at the base and avoid wetting leaves to reduce blight risk.': 'ಎಲೆಗಳನ್ನು ತೇವಗೊಳಿಸದೆ ಗಿಡದ ಬುಡಕ್ಕೆ ನೀರು ಹಾಕಿ. ಇದರಿಂದ ಅಂಗಮಾರಿ ರೋಗದ ಅಪಾಯ ಕಡಿಮೆಯಾಗುತ್ತದೆ.', 'Roots are growing: keep soil evenly moist and apply the first fertilizer dose as advised locally.': 'ಬೇರುಗಳು ಬೆಳೆಯುತ್ತಿವೆ. ಮಣ್ಣಿನಲ್ಲಿ ಸಮತಟ್ಟಾದ ತೇವಾಂಶ ಕಾಪಾಡಿ ಮತ್ತು ಸ್ಥಳೀಯ ಸಲಹೆಯಂತೆ ಮೊದಲ ಗೊಬ್ಬರದ ಪ್ರಮಾಣ ಹಾಕಿ.', 'Peak water demand: avoid any moisture stress now, it hurts yield the most.': 'ಈ ಹಂತದಲ್ಲಿ ನೀರಿನ ಅವಶ್ಯಕತೆ ಅತ್ಯಧಿಕವಾಗಿರುತ್ತದೆ. ತೇವಾಂಶದ ಕೊರತೆಯಾಗದಂತೆ ನೋಡಿಕೊಳ್ಳಿ; ಇದು ಇಳುವರಿಯನ್ನು ಹೆಚ್ಚು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.', 'Water need is falling: reduce irrigation gradually and plan harvest around dry weather.': 'ಈಗ ನೀರಿನ ಅವಶ್ಯಕತೆ ಕಡಿಮೆಯಾಗುತ್ತಿದೆ. ನೀರಾವರಿಯನ್ನು ನಿಧಾನವಾಗಿ ಕಡಿಮೆ ಮಾಡಿ ಮತ್ತು ಒಣ ಹವಾಮಾನದಲ್ಲಿ ಕೊಯ್ಲು ಯೋಜಿಸಿ.', 'Paddy is usually kept flooded; treat the amount shown as the top-up needed.': 'ಭತ್ತದ ಗದ್ದೆಯಲ್ಲಿ ಸಾಮಾನ್ಯವಾಗಿ ನೀರು ನಿಲ್ಲಿಸಲಾಗುತ್ತದೆ. ತೋರಿಸಿರುವ ಪ್ರಮಾಣವನ್ನು ಹೆಚ್ಚುವರಿಯಾಗಿ ಬೇಕಾದ ನೀರೆಂದು ಪರಿಗಣಿಸಿ.', 'Excess water at flowering causes boll drop; avoid waterlogging.': 'ಹೂ ಬಿಡುವ ಹಂತದಲ್ಲಿ ಹೆಚ್ಚು ನೀರು ಕಾಯಿಗಳು ಉದುರುವಂತೆ ಮಾಡಬಹುದು. ಹೊಲದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಿ.', 'Heavy feeder of water; mulch trash to cut evaporation.': 'ಈ ಬೆಳೆಗೆ ಹೆಚ್ಚು ನೀರು ಬೇಕಾಗುತ್ತದೆ. ಆವಿಯಾಗುವಿಕೆ ಕಡಿಮೆ ಮಾಡಲು ಬೆಳೆ ಅವಶೇಷಗಳಿಂದ ಮಲ್ಚಿಂಗ್ ಮಾಡಿ.', 'Crown-root and flowering stages are most sensitive to dry soil.': 'ಕಿರೀಟ ಬೇರು ಮತ್ತು ಹೂ ಬಿಡುವ ಹಂತಗಳು ಒಣ ಮಣ್ಣಿಗೆ ಹೆಚ್ಚು ಸೂಕ್ಷ್ಮವಾಗಿವೆ.', 'Red soil is low in organic matter: add compost or FYM and apply phosphorus near the roots.': 'ಕೆಂಪು ಮಣ್ಣಿನಲ್ಲಿ ಸಾವಯವ ಪದಾರ್ಥ ಕಡಿಮೆ ಇರುತ್ತದೆ. ಕಾಂಪೋಸ್ಟ್ ಅಥವಾ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಸೇರಿಸಿ ಮತ್ತು ಬೇರುಗಳ ಬಳಿ ರಂಜಕ ಹಾಕಿ.', 'Sandy soil leaches nutrients: split nitrogen into 3-4 smaller doses and use mulch or compost to hold water.': 'ಮರಳು ಮಣ್ಣಿನಲ್ಲಿ ಪೋಷಕಾಂಶಗಳು ಬೇಗ ತೊಳೆದು ಹೋಗುತ್ತವೆ. ಸಾರಜನಕವನ್ನು 3–4 ಸಣ್ಣ ಪ್ರಮಾಣಗಳಲ್ಲಿ ನೀಡಿ ಮತ್ತು ತೇವಾಂಶ ಉಳಿಸಲು ಮಲ್ಚ್ ಅಥವಾ ಕಾಂಪೋಸ್ಟ್ ಬಳಸಿ.', 'Loamy soil holds water and nutrients well: standard split doses work.': 'ಗೋಡು ಮಣ್ಣು ನೀರು ಮತ್ತು ಪೋಷಕಾಂಶಗಳನ್ನು ಚೆನ್ನಾಗಿ ಹಿಡಿದಿಡುತ್ತದೆ. ಸಾಮಾನ್ಯ ವಿಭಜಿತ ಗೊಬ್ಬರ ಪ್ರಮಾಣಗಳನ್ನು ಬಳಸಬಹುದು.', 'Clay soil drains slowly: avoid waterlogging, make drainage channels and avoid working it when wet.': 'ಜೇಡಿ ಮಣ್ಣಿನಲ್ಲಿ ನೀರು ನಿಧಾನವಾಗಿ ಹರಿಯುತ್ತದೆ. ನೀರು ನಿಲ್ಲದಂತೆ ಕಾಲುವೆ ಮಾಡಿ ಮತ್ತು ಮಣ್ಣು ಒದ್ದೆಯಾಗಿರುವಾಗ ಹೊಲದ ಕೆಲಸ ಮಾಡಬೇಡಿ.', 'Black soil cracks when dry and sticks when wet: apply P and K as basal dose and avoid field work in wet spells.': 'ಕಪ್ಪು ಮಣ್ಣು ಒಣಗಿದಾಗ ಬಿರುಕು ಬಿಡುತ್ತದೆ ಮತ್ತು ಒದ್ದೆಯಾದಾಗ ಅಂಟುತ್ತದೆ. ರಂಜಕ ಮತ್ತು ಪೊಟಾಶ್ ಅನ್ನು ಮೂಲ ಗೊಬ್ಬರವಾಗಿ ಹಾಕಿ; ಮಳೆಗಾಲದಲ್ಲಿ ಹೊಲದ ಕೆಲಸ ತಪ್ಪಿಸಿ.', 'Your crop match': 'ನಿಮ್ಮ ಬೆಳೆ ಹೊಂದಾಣಿಕೆ', 'average temperature': 'ಸರಾಸರಿ ತಾಪಮಾನ', 'AI picked': 'AI ಆಯ್ಕೆ ಮಾಡಿದೆ', 'Prices, yields and fit scores are sample values. Check with your local market and agriculture office.': 'ಬೆಲೆ, ಇಳುವರಿ ಮತ್ತು ಹೊಂದಾಣಿಕೆ ಅಂಕಗಳು ಮಾದರಿ ಮೌಲ್ಯಗಳಾಗಿವೆ. ಸ್ಥಳೀಯ ಮಾರುಕಟ್ಟೆ ಮತ್ತು ಕೃಷಿ ಕಚೇರಿಯಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.', 'Yield, cost and price are sample defaults. Update them from MSP, Agmarknet or local data.': 'ಇಳುವರಿ, ವೆಚ್ಚ ಮತ್ತು ಬೆಲೆಗಳು ಮಾದರಿ ಮೌಲ್ಯಗಳಾಗಿವೆ. MSP, Agmarknet ಅಥವಾ ಸ್ಥಳೀಯ ಮಾಹಿತಿಯಿಂದ ನವೀಕರಿಸಿ.', 'Rice': 'ಅಕ್ಕಿ', 'Wheat': 'ಗೋಧಿ', 'Maize': 'ಮೆಕ್ಕೆಜೋಳ', 'Tomato': 'ಟೊಮೆಟೊ', 'Cotton': 'ಹತ್ತಿ', 'Sugarcane': 'ಕಬ್ಬು', 'Ragi': 'ರಾಗಿ'}, 'te': {'Seedlings are shallow-rooted: give light, frequent water and protect from heat.': 'మొలకల వేర్లు పైపైనే ఉంటాయి. తక్కువ పరిమాణంలో తరచుగా నీరు ఇవ్వండి; వేడి నుంచి కాపాడండి.', 'Water at the base and avoid wetting leaves to reduce blight risk.': 'ఆకులు తడవకుండా మొక్క అడుగున నీరు పెట్టండి; తెగులు ప్రమాదం తగ్గుతుంది.', 'Roots are growing: keep soil evenly moist and apply the first fertilizer dose as advised locally.': 'వేర్లు పెరుగుతున్నాయి. నేలలో సమానమైన తేమ ఉంచండి; స్థానిక సలహా ప్రకారం మొదటి ఎరువు మోతాదు వేయండి.', 'Peak water demand: avoid any moisture stress now, it hurts yield the most.': 'ఈ దశలో నీటి అవసరం అత్యధికం. తేమ కొరత రాకుండా చూడండి; దిగుబడిపై ఎక్కువ ప్రభావం ఉంటుంది.', 'Water need is falling: reduce irrigation gradually and plan harvest around dry weather.': 'ఇప్పుడు నీటి అవసరం తగ్గుతోంది. నీటిపారుదల క్రమంగా తగ్గించి, పొడి వాతావరణంలో కోతకు ప్రణాళిక చేయండి.', 'Paddy is usually kept flooded; treat the amount shown as the top-up needed.': 'వరి పొలంలో సాధారణంగా నీరు నిల్వ ఉంచుతారు. చూపిన పరిమాణాన్ని అదనంగా ఇవ్వాల్సిన నీరుగా పరిగణించండి.', 'Excess water at flowering causes boll drop; avoid waterlogging.': 'పూత దశలో అధిక నీరు కాయలు రాలడానికి కారణమవుతుంది. నీరు నిల్వ ఉండనివ్వకండి.', 'Heavy feeder of water; mulch trash to cut evaporation.': 'ఈ పంటకు ఎక్కువ నీరు అవసరం. ఆవిరీభవనం తగ్గించడానికి పంట అవశేషాలతో మల్చింగ్ చేయండి.', 'Crown-root and flowering stages are most sensitive to dry soil.': 'కిరీట వేరు మరియు పూత దశల్లో నేల ఎండిపోతే పంటకు ఎక్కువ నష్టం కలుగుతుంది.', 'Your crop match': 'మీ పంట అనుకూలత', 'average temperature': 'సగటు ఉష్ణోగ్రత', 'AI picked': 'AI ఎంపిక చేసింది', 'Rice': 'వరి', 'Wheat': 'గోధుమ', 'Maize': 'మొక్కజొన్న', 'Tomato': 'టమాటా', 'Cotton': 'పత్తి', 'Sugarcane': 'చెరకు', 'Ragi': 'రాగి'}}.items():
    ADVICE_PHRASES.setdefault(_lang, {}).update(_items)

