def _translate_dynamic_alert(text, lang):
    """Translate numeric weather alerts without changing their measured values."""
    import re
    if lang not in ("hi", "kn", "te"):
        return None
    hi = lang == "hi"
    kn = lang == "kn"
    def tr(hi_text, kn_text, te_text):
        return hi_text if hi else kn_text if kn else te_text
    m = re.match(r"Heatwave risk \(([\d.]+)°C\): irrigate early morning or evening\.?", text)
    if m:
        n=m.group(1)
        return tr(f"लू का खतरा ({n}°C): सुबह जल्दी या शाम को सिंचाई करें।",
                  f"ಬಿಸಿಗಾಳಿಯ ಅಪಾಯ ({n}°C): ಮುಂಜಾನೆ ಅಥವಾ ಸಂಜೆ ನೀರಾವರಿ ಮಾಡಿ.",
                  f"వడగాలుల ప్రమాదం ({n}°C): ఉదయం లేదా సాయంత్రం నీరు పెట్టండి.")
    m = re.match(r"Frost risk \(([\d.]+)°C\): cover or irrigate lightly the evening before\.?", text)
    if m:
        n=m.group(1)
        return tr(f"पाला पड़ने का खतरा ({n}°C): पिछली शाम पौधों को ढकें या हल्की सिंचाई करें।",
                  f"ಹಿಮಪಾತದ ಅಪಾಯ ({n}°C): ಹಿಂದಿನ ಸಂಜೆ ಗಿಡಗಳನ್ನು ಮುಚ್ಚಿ ಅಥವಾ ಸ್ವಲ್ಪ ನೀರು ಹಾಕಿ.",
                  f"మంచు ప్రమాదం ({n}°C): ముందు రోజు సాయంత్రం మొక్కలను కప్పండి లేదా కొద్దిగా నీరు పెట్టండి.")
    m = re.match(r"Very heavy rain \(([\d.]+) mm\): clear drainage, skip fertilizer and spraying\.?", text)
    if m:
        n=m.group(1)
        return tr(f"అత్యధిక వర్షం ({n} మి.మీ.): నీటి కాలువలను శుభ్రం చేయండి; ఎరువులు వేయడం, పిచికారీ చేయడం ఆపండి." if False else f"बहुत भारी बारिश ({n} मिमी): जल निकासी नालियाँ साफ करें; खाद और छिड़काव न करें।",
                  f"ಅತಿ ಹೆಚ್ಚು ಮಳೆ ({n} ಮಿ.ಮೀ.): ನೀರು ಹರಿಯುವ ಕಾಲುವೆಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ; ಗೊಬ್ಬರ ಮತ್ತು ಸಿಂಪಡಣೆ ಮಾಡಬೇಡಿ.",
                  f"అతి భారీ వర్షం ({n} మి.మీ.): నీటి కాలువలను శుభ్రం చేయండి; ఎరువులు వేయడం, పిచికారీ చేయడం మానండి.")
    m = re.match(r"Heavy rain likely \(([\d.]+) mm\): postpone spraying and fertilizer\.?", text)
    if m:
        n=m.group(1)
        return tr(f"भारी बारिश की संभावना ({n} मिमी): छिड़काव और खाद डालना टालें।",
                  f"ಭಾರಿ ಮಳೆಯ ಸಾಧ್ಯತೆ ({n} ಮಿ.ಮೀ.): ಸಿಂಪಡಣೆ ಮತ್ತು ಗೊಬ್ಬರ ಹಾಕುವುದನ್ನು ಮುಂದೂಡಿ.",
                  f"భారీ వర్షం వచ్చే అవకాశం ఉంది ({n} మి.మీ.): పిచికారీ మరియు ఎరువుల వేయడాన్ని వాయిదా వేయండి.")
    m = re.match(r"Strong wind \(([\d.]+) km/h\): do not spray pesticides\.?", text)
    if m:
        n=m.group(1)
        return tr(f"तेज़ हवा ({n} किमी/घंटा): कीटनाशकों का छिड़काव न करें।",
                  f"ಬಲವಾದ ಗಾಳಿ ({n} ಕಿ.ಮೀ./ಗಂಟೆ): ಕೀಟನಾಶಕ ಸಿಂಪಡಣೆ ಮಾಡಬೇಡಿ.",
                  f"బలమైన గాలి ({n} కి.మీ./గం.): పురుగుమందులు పిచికారీ చేయవద్దు.")
    m = re.match(r"Dry and hot spell ahead: watch for crop water stress\.?", text)
    if m:
        return tr("आगे गर्म और सूखा मौसम रहेगा: फसल में पानी की कमी के लक्षण देखें.",
                  "ಮುಂದೆ ಬಿಸಿ ಮತ್ತು ಒಣ ಹವಾಮಾನ ಇರಲಿದೆ: ಬೆಳೆಯಲ್ಲಿ ನೀರಿನ ಕೊರತೆಯ ಲಕ್ಷಣಗಳನ್ನು ಗಮನಿಸಿ.",
                  "ముందు వేడి, పొడి వాతావరణం ఉండవచ్చు: పంటలో నీటి కొరత లక్షణాలను గమనించండి.")
    m = re.match(r"Heavy rain \(([\d.]+) mm\) expected: clear drains(?:; harvest early if the crop is ready)?\.?", text)
    if m:
        n=m.group(1)
        return tr(f"భారీ వర్షం ({n} మి.మీ.) వచ్చే అవకాశం ఉంది: నీటి కాలువలను శుభ్రం చేయండి." if False else f"भारी बारिश ({n} मिमी) की संभावना है: जल निकासी नालियाँ साफ करें।",
                  f"ಭಾರಿ ಮಳೆ ({n} ಮಿ.ಮೀ.) ನಿರೀಕ್ಷಿಸಲಾಗಿದೆ: ನೀರು ಹರಿಯುವ ಕಾಲುವೆಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ.",
                  f"భారీ వర్షం ({n} మి.మీ.) వచ్చే అవకాశం ఉంది: నీటి కాలువలను శుభ్రం చేయండి.")
    m = re.match(r"Hot day \(([\d.]+)°C\): irrigate early morning or evening, avoid midday field work\.?", text)
    if m:
        n=m.group(1)
        return tr(f"गर्म दिन ({n}°C): सुबह जल्दी या शाम को सिंचाई करें; दोपहर में खेत का काम न करें।",
                  f"ಬಿಸಿ ದಿನ ({n}°C): ಮುಂಜಾನೆ ಅಥವಾ ಸಂಜೆ ನೀರಾವರಿ ಮಾಡಿ; ಮಧ್ಯಾಹ್ನ ಹೊಲದ ಕೆಲಸ ಮಾಡಬೇಡಿ.",
                  f"వేడి రోజు ({n}°C): ఉదయం లేదా సాయంత్రం నీరు పెట్టండి; మధ్యాహ్నం పొలంలో పని చేయవద్దు.")
    return None




def _translate_generic_stage_action(text, lang):
    """Translate generated stage templates for crops beyond the six core crops."""
    if lang not in ("hi", "kn", "te"):
        return None
    import re
    patterns = {
      "prepare": r"Prepare a fine seedbed and sow healthy, certified (.+?) seed at the locally recommended spacing\.?",
      "moist": r"Keep the root zone evenly moist and remove weeds around the (.+?) crop\.?",
      "monitor": r"Monitor flowering and early fruit or grain formation; avoid moisture stress\.?",
      "mature": r"Reduce irrigation as the crop matures and harvest at the locally recommended maturity\.?"
    }
    if re.fullmatch(patterns["prepare"], text):
        crop=re.fullmatch(patterns["prepare"], text).group(1)
        prefix,suffix={
          "hi":("अच्छी तरह तैयार खेत में स्वस्थ, प्रमाणित "," के बीज स्थानीय अनुशंसित दूरी पर बोएँ।"),
          "kn":("ಉತ್ತಮವಾಗಿ ಸಿದ್ಧಪಡಿಸಿದ ಹೊಲದಲ್ಲಿ ಆರೋಗ್ಯಕರ, ಪ್ರಮಾಣಿತ "," ಬೀಜಗಳನ್ನು ಸ್ಥಳೀಯವಾಗಿ ಶಿಫಾರಸು ಮಾಡಿದ ಅಂತರದಲ್ಲಿ ಬಿತ್ತನೆ ಮಾಡಿ."),
          "te":("చక్కగా సిద్ధం చేసిన పొలంలో ఆరోగ్యకరమైన, ధృవీకరించిన "," విత్తనాలను స్థానికంగా సూచించిన దూరంలో విత్తండి.")
        }[lang]
        return prefix+crop+suffix
    if re.fullmatch(patterns["moist"], text):
        crop=re.fullmatch(patterns["moist"], text).group(1)
        prefix,suffix={
          "hi":("जड़ों के आसपास मिट्टी में समान नमी रखें और "," की फसल के आसपास निराई करें।"),
          "kn":("ಬೇರುಗಳ ಸುತ್ತ ಮಣ್ಣಿನಲ್ಲಿ ಸಮಾನ ತೇವಾಂಶ ಇರಿಸಿ ಮತ್ತು "," ಬೆಳೆಯ ಸುತ್ತಲಿನ ಕಳೆ ತೆಗೆಯಿರಿ."),
          "te":("వేర్ల చుట్టూ నేలలో సమాన తేమ ఉండేలా చూసి, "," పంట చుట్టూ కలుపు తీయండి.")
        }[lang]
        return prefix+crop+suffix
    if re.fullmatch(patterns["monitor"], text):
        return {"hi":"फूल आने तथा शुरुआती फल या दाने बनने की अवस्था पर नजर रखें। मिट्टी में नमी की कमी न होने दें।",
                "kn":"ಹೂ ಬಿಡುವಿಕೆ ಮತ್ತು ಆರಂಭಿಕ ಹಣ್ಣು ಅಥವಾ ಕಾಳುಗಳ ಬೆಳವಣಿಗೆಯನ್ನು ಗಮನಿಸಿ; ತೇವಾಂಶದ ಕೊರತೆ ಆಗದಂತೆ ನೋಡಿ.",
                "te":"పూత మరియు ప్రారంభ కాయ లేదా గింజ ఏర్పడే దశను గమనించండి; తేమ కొరత రాకుండా చూడండి."}[lang]
    if re.fullmatch(patterns["mature"], text):
        return {"hi":"फसल पकने पर सिंचाई धीरे-धीरे कम करें और स्थानीय सलाह के अनुसार पकने पर कटाई करें।",
                "kn":"ಬೆಳೆ ಪಕ್ವವಾಗುವಾಗ ನೀರಾವರಿಯನ್ನು ಕ್ರಮೇಣ ಕಡಿಮೆ ಮಾಡಿ ಮತ್ತು ಸ್ಥಳೀಯ ಶಿಫಾರಸಿನಂತೆ ಕೊಯ್ಲು ಮಾಡಿ.",
                "te":"పంట పక్వానికి వచ్చే కొద్దీ నీరు పెట్టడం తగ్గించి, స్థానిక సూచనల ప్రకారం కోయండి."}[lang]
    return None


def translate_advice_text(text, lang="en"):
    if not isinstance(text, str) or lang == "en":
        return text
    phrases = ADVICE_PHRASES.get(lang, {})
    dynamic_alert = _translate_dynamic_alert(text, lang)
    if dynamic_alert is not None:
        return dynamic_alert
    generic_stage = _translate_generic_stage_action(text, lang)
    if generic_stage is not None:
        return generic_stage
    dynamic_forecast = _translate_dynamic_forecast(text, lang)
    if dynamic_forecast is not None:
        return dynamic_forecast
    dynamic_hi_kn = _translate_dynamic_hi_kn(text, lang)
    if dynamic_hi_kn is not None:
        return dynamic_hi_kn
    if text in phrases:
        return phrases[text]
    import re
    # Dynamic irrigation recommendation keeps all numeric values unchanged.
    if lang == "te":
        m = re.match(r"Apply about ([\d,.]+) mm \(about ([\d,.]+) litres per acre\) to refill the root zone\.", text)
        if m: return f"వేర్ల ప్రాంతాన్ని తిరిగి తేమతో నింపడానికి సుమారు {m.group(1)} మి.మీ. నీరు (ఎకరానికి సుమారు {m.group(2)} లీటర్లు) ఇవ్వండి."
        m = re.match(r"Soil will hit the stress limit by tonight\. Plan about ([\d,.]+) mm\.", text)
        if m: return f"ఈ రాత్రికి నేలలో తేమ పంటకు ఒత్తిడి కలిగించే స్థాయికి చేరుతుంది. సుమారు {m.group(1)} మి.మీ. నీటికి ప్రణాళిక చేయండి."
        m = re.match(r"Soil is getting dry but about ([\d,.]+) mm of rain is likely today\. Re-check tomorrow\.", text)
        if m: return f"నేల ఎండుతోంది. అయితే ఈరోజు సుమారు {m.group(1)} మి.మీ. వర్షం పడే అవకాశం ఉంది. రేపు మళ్లీ పరిశీలించండి."
        m = re.match(r"Irrigate in (\d+) day\(s\)", text)
        if m: return f"{m.group(1)} రోజుల్లో నీటిపారుదల చేయండి"
        m = re.match(r"Forecast for the next (\d+) days: highs ([\d.]+) to ([\d.]+)°C, total rain ([\d.]+) mm(?:, wettest day ([0-9-]+) \(([\d.]+) mm\))?\.?", text)
        if m:
            tail = f", అత్యధిక వర్షం {m.group(5)}న ({m.group(6)} మి.మీ.)" if m.group(5) else ""
            return f"తదుపరి {m.group(1)} రోజుల అంచనా: గరిష్ఠ ఉష్ణోగ్రత {m.group(2)}–{m.group(3)}°C, మొత్తం వర్షపాతం {m.group(4)} మి.మీ.{tail}"
        m = re.match(r"Irrigation: (.+?)\. (.+)", text)
        if m: return "నీటిపారుదల: " + translate_advice_text(m.group(1),lang) + ". " + translate_advice_text(m.group(2),lang)
        m = re.match(r"(Hot day|Heatwave risk) \(([\d.]+)°C\): irrigate early morning or evening, avoid midday field work\.?", text)
