def translate_advice_payload(payload, lang="en"):
    """Translate farmer-facing generated advice fields while preserving data/numbers."""
    if lang == "en" or lang not in ADVICE_PHRASES:
        return payload
    fields = ("action", "detail", "outlook", "why", "tips", "steps", "alerts", "care")
    for key in fields:
        value = payload.get(key)
        if isinstance(value, str):
            payload[key] = translate_advice_text(value, lang)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, str):
                    # Replace in place for simple lists.
                    idx = value.index(item)
                    value[idx] = translate_advice_text(item, lang)
                elif isinstance(item, dict):
                    for subkey in ("text", "msg"):
                        if isinstance(item.get(subkey), str):
                            item[subkey] = translate_advice_text(item[subkey], lang)
    for key in ("crop_rec", "fert", "profit"):
        obj = payload.get(key)
        if isinstance(obj, dict):
            for subkey in ("msg", "verdict"):
                if isinstance(obj.get(subkey), str): obj[subkey] = translate_advice_text(obj[subkey], lang)
            for subkey in ("schedule", "notes"):
                if isinstance(obj.get(subkey), list): obj[subkey] = [translate_advice_text(x,lang) for x in obj[subkey]]
    # Localize season and weather source labels used in the result chips.
    payload["season"] = translate_advice_text(payload.get("season", ""), lang)
    payload["source_label"] = translate_advice_text("Live weather" if payload.get("source")=="live" else "Demo weather",lang)
    return payload


# v7.7: complete common action, next-step and crop-care translations.
for _lang, _items in {'hi': {'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'पौधों को सहारा दें, निराई करें और ऊपर से खाद डालें। अर्ली ब्लाइट रोग और सफेद मक्खी की नियमित जाँच करें।', 'Irrigate lightly and regularly; spray only on dry days.': 'हल्की मात्रा में नियमित सिंचाई करें। छिड़काव केवल सूखे दिनों में करें।', 'Transplant in the evening, irrigate lightly and shade young plants.': 'शाम के समय रोपाई करें, हल्की सिंचाई करें और छोटे पौधों को छाया दें।', 'Harvest at the breaker stage; keep water off the fruits.': 'फल रंग बदलना शुरू करें तब कटाई करें। फलों पर पानी न पड़ने दें।', 'Loamy soil holds water and nutrients well: standard split doses work.': 'दोमट मिट्टी पानी और पोषक तत्व अच्छी तरह रोकती है। खाद की सामान्य विभाजित खुराकें उपयोग करें।', 'Best dry, calm day for spraying and fertilizer top-dressing.': 'छिड़काव और ऊपर से खाद डालने के लिए आज का दिन सूखा और कम हवा वाला है।', 'No dry, calm day in the forecast: hold off spraying and fertilizer.': 'पूर्वानुमान में कोई सूखा और कम हवा वाला दिन नहीं है। छिड़काव और खाद डालना अभी टालें।', 'Prepare the land, buy certified seed and sow on the first dry day once soil moisture is adequate.': 'खेत तैयार करें और प्रमाणित बीज खरीदें। मिट्टी में पर्याप्त नमी होने पर पहले सूखे दिन बुवाई करें।', 'Wet weather raises fungal disease risk: scout for leaf spots or blight and spray only on dry days.': 'गीले मौसम में फफूंद रोग का खतरा बढ़ता है। पत्तों पर धब्बे या झुलसा रोग के लक्षण देखें और केवल सूखे दिन छिड़काव करें।', 'Hot, dry weather favours mites, aphids and hoppers: scout twice a week.': 'गर्म और सूखे मौसम में माइट, माहू और हॉपर बढ़ सकते हैं। सप्ताह में दो बार फसल की जाँच करें।', 'Your crop care for': 'आपकी फसल की देखभाल:', 'Care for your': 'आपकी फसल की देखभाल:', 'sample data: no internet': 'नमूना डेटा: इंटरनेट उपलब्ध नहीं है'}, 'kn': {'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'ಗಿಡಗಳಿಗೆ ಆಧಾರ ನೀಡಿ, ಕಳೆ ತೆಗೆಯಿರಿ ಮತ್ತು ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ. ಆರಂಭಿಕ ಎಲೆ ಅಂಗಮಾರಿ ರೋಗ ಹಾಗೂ ಬಿಳಿ ನೊಣಗಳಿಗಾಗಿ ಪರಿಶೀಲಿಸಿ.', 'Irrigate lightly and regularly; spray only on dry days.': 'ಕಡಿಮೆ ಪ್ರಮಾಣದಲ್ಲಿ ನಿಯಮಿತವಾಗಿ ನೀರಾವರಿ ಮಾಡಿ. ಒಣ ದಿನಗಳಲ್ಲಿ ಮಾತ್ರ ಸಿಂಪಡಣೆ ಮಾಡಿ.', 'Transplant in the evening, irrigate lightly and shade young plants.': 'ಸಂಜೆ ಸಮಯದಲ್ಲಿ ನಾಟಿ ಮಾಡಿ, ಸ್ವಲ್ಪ ನೀರು ಹಾಕಿ ಮತ್ತು ಎಳೆಯ ಗಿಡಗಳಿಗೆ ನೆರಳು ಒದಗಿಸಿ.', 'Harvest at the breaker stage; keep water off the fruits.': 'ಹಣ್ಣು ಬಣ್ಣ ಬದಲಾಯಿಸಲು ಆರಂಭಿಸಿದ ಹಂತದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡಿ. ಹಣ್ಣುಗಳ ಮೇಲೆ ನೀರು ಬೀಳದಂತೆ ನೋಡಿಕೊಳ್ಳಿ.', 'Loamy soil holds water and nutrients well: standard split doses work.': 'ಗೋಡು ಮಣ್ಣು ನೀರು ಮತ್ತು ಪೋಷಕಾಂಶಗಳನ್ನು ಚೆನ್ನಾಗಿ ಹಿಡಿದಿಡುತ್ತದೆ. ಗೊಬ್ಬರವನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ವಿಭಜಿತ ಪ್ರಮಾಣಗಳಲ್ಲಿ ನೀಡಿ.', 'Best dry, calm day for spraying and fertilizer top-dressing.': 'ಸಿಂಪಡಣೆ ಮತ್ತು ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಲು ಇಂದು ಒಣ ಹಾಗೂ ಗಾಳಿ ಕಡಿಮೆ ಇರುವ ಉತ್ತಮ ದಿನ.', 'No dry, calm day in the forecast: hold off spraying and fertilizer.': 'ಮುನ್ಸೂಚನೆಯಲ್ಲಿ ಒಣ ಹಾಗೂ ಗಾಳಿ ಕಡಿಮೆ ಇರುವ ದಿನವಿಲ್ಲ. ಸಿಂಪಡಣೆ ಮತ್ತು ಗೊಬ್ಬರ ಹಾಕುವುದನ್ನು ಮುಂದೂಡಿ.', 'Prepare the land, buy certified seed and sow on the first dry day once soil moisture is adequate.': 'ಭೂಮಿಯನ್ನು ಸಿದ್ಧಪಡಿಸಿ, ಪ್ರಮಾಣಿತ ಬೀಜಗಳನ್ನು ಖರೀದಿಸಿ. ಮಣ್ಣಿನಲ್ಲಿ ಸಾಕಷ್ಟು ತೇವವಿದ್ದಾಗ ಮೊದಲ ಒಣ ದಿನ ಬಿತ್ತನೆ ಮಾಡಿ.', 'Wet weather raises fungal disease risk: scout for leaf spots or blight and spray only on dry days.': 'ಮಳೆಯ ವಾತಾವರಣದಲ್ಲಿ ಶಿಲೀಂಧ್ರ ರೋಗದ ಅಪಾಯ ಹೆಚ್ಚುತ್ತದೆ. ಎಲೆ ಚುಕ್ಕೆ ಅಥವಾ ಅಂಗಮಾರಿ ಲಕ್ಷಣಗಳನ್ನು ಗಮನಿಸಿ, ಒಣ ದಿನಗಳಲ್ಲಿ ಮಾತ್ರ ಸಿಂಪಡಣೆ ಮಾಡಿ.', 'Hot, dry weather favours mites, aphids and hoppers: scout twice a week.': 'ಬಿಸಿ ಮತ್ತು ಒಣ ಹವಾಮಾನದಲ್ಲಿ ಮೈಟ್ಸ್, ಹೇನು ಮತ್ತು ಹಾಪರ್ ಕೀಟಗಳು ಹೆಚ್ಚಾಗಬಹುದು. ವಾರಕ್ಕೆ ಎರಡು ಬಾರಿ ಪರಿಶೀಲಿಸಿ.', 'Your crop care for': 'ನಿಮ್ಮ ಬೆಳೆಯ ಆರೈಕೆ:', 'Care for your': 'ನಿಮ್ಮ ಬೆಳೆಯ ಆರೈಕೆ:', 'sample data: no internet': 'ಮಾದರಿ ಡೇಟಾ: ಇಂಟರ್ನೆಟ್ ಇಲ್ಲ'}, 'te': {'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'మొక్కలకు కర్రలతో ఆధారం ఇవ్వండి, కలుపు తీయండి, పై ఎరువు వేయండి. ఎర్లీ బ్లైట్ తెగులు మరియు తెల్లదోమలను గమనించండి.', 'Irrigate lightly and regularly; spray only on dry days.': 'తక్కువ పరిమాణంలో క్రమం తప్పకుండా నీరు పెట్టండి. పొడి రోజుల్లో మాత్రమే పిచికారీ చేయండి.', 'Transplant in the evening, irrigate lightly and shade young plants.': 'సాయంత్రం నాట్లు వేయండి, తక్కువ నీరు పెట్టండి మరియు చిన్న మొక్కలకు నీడ కల్పించండి.', 'Harvest at the breaker stage; keep water off the fruits.': 'కాయలు రంగు మారడం ప్రారంభించిన దశలో కోయండి. పండ్లపై నీరు పడకుండా చూడండి.', 'Loamy soil holds water and nutrients well: standard split doses work.': 'లోమీ నేల నీరు, పోషకాలను బాగా నిల్వ చేస్తుంది. ఎరువులను సాధారణంగా విడతల వారీగా వేయండి.', 'Best dry, calm day for spraying and fertilizer top-dressing.': 'పిచికారీ మరియు పై ఎరువు వేయడానికి ఈ రోజు పొడిగా, గాలి తక్కువగా ఉండే మంచి రోజు.', 'No dry, calm day in the forecast: hold off spraying and fertilizer.': 'వాతావరణ సూచనలో పొడి, గాలి తక్కువగా ఉండే రోజు లేదు. పిచికారీ మరియు ఎరువుల వేయడాన్ని వాయిదా వేయండి.', 'Prepare the land, buy certified seed and sow on the first dry day once soil moisture is adequate.': 'భూమిని సిద్ధం చేసి, ధృవీకరించిన విత్తనాలు కొనండి. నేలలో తగినంత తేమ ఉన్న మొదటి పొడి రోజున విత్తండి.', 'Wet weather raises fungal disease risk: scout for leaf spots or blight and spray only on dry days.': 'తడి వాతావరణంలో శిలీంధ్ర వ్యాధుల ప్రమాదం పెరుగుతుంది. ఆకుల మచ్చలు లేదా తెగులు లక్షణాలను గమనించి, పొడి రోజుల్లో మాత్రమే పిచికారీ చేయండి.', 'Hot, dry weather favours mites, aphids and hoppers: scout twice a week.': 'వేడి, పొడి వాతావరణంలో మైట్స్, పేనులు మరియు హాపర్ పురుగులు పెరగవచ్చు. వారానికి రెండుసార్లు పరిశీలించండి.', 'Your crop care for': 'మీ పంట సంరక్షణ:', 'Care for your': 'మీ పంట సంరక్షణ:', 'sample data: no internet': 'నమూనా డేటా: ఇంటర్నెట్ లేదు'}}.items():
    ADVICE_PHRASES.setdefault(_lang, {}).update(_items)


# v7.9: crop-stage action translations for generated next-step and crop-care cards.
_STAGE_ACTION_TRANSLATIONS = {'hi': {'Transplant healthy seedlings, keep 2-3 cm water and apply basal fertilizer.': 'स्वस्थ पौधों की रोपाई करें, खेत में 2–3 सेमी पानी रखें और बुवाई के समय आधार खाद डालें।', 'Weed at 20-25 days, top-dress urea at tillering and scout for stem borer.': '20–25 दिनों में निराई करें, कल्ले निकलने की अवस्था में यूरिया की ऊपरी खुराक डालें और तना छेदक कीट की जाँच करें।', 'Keep about 5 cm water at flowering; watch for blast and planthopper.': 'फूल आने के समय खेत में लगभग 5 सेमी पानी रखें। ब्लास्ट रोग और प्लांट हॉपर कीट पर नजर रखें।', 'Drain the field about 10 days before harvest; harvest at 80-85% golden grains.': 'कटाई से लगभग 10 दिन पहले खेत का पानी निकाल दें। जब 80–85% दाने सुनहरे हो जाएँ, तब कटाई करें।', 'Sow at the right depth; give the first irrigation at 20-25 days (crown root stage).': 'बीज सही गहराई पर बोएँ। 20–25 दिनों में (क्राउन रूट अवस्था पर) पहली सिंचाई करें।', 'Weed at 30-35 days, top-dress urea and irrigate at tillering.': '30–35 दिनों में निराई करें, यूरिया की ऊपरी खुराक डालें और कल्ले निकलने की अवस्था में सिंचाई करें।', 'Irrigate at flowering and grain filling; scout for rust.': 'फूल आने और दाने भरने की अवस्था में सिंचाई करें। रतुआ रोग के लक्षण देखें।', 'Stop irrigation as grains harden; harvest when grains are hard and dry.': 'दाने सख्त होने पर सिंचाई बंद करें। दाने सख्त और सूखे होने पर कटाई करें।', 'Thin plants, gap-fill and weed early.': 'पौधों की उचित छँटाई करें, खाली जगहों पर पौधे लगाएँ और शुरुआती अवस्था में निराई करें।', 'Earth up and top-dress urea at knee height; scout for fall armyworm.': 'पौधों की जड़ों के पास मिट्टी चढ़ाएँ और घुटने की ऊँचाई पर यूरिया की ऊपरी खुराक डालें। फॉल आर्मीवर्म कीट की जाँच करें।', 'Never let soil dry at tasseling and silking; irrigate on time.': 'भुट्टा निकलने और रेशे आने की अवस्था में मिट्टी सूखने न दें। समय पर सिंचाई करें।', 'Let cobs dry on the plant; harvest when husks turn dry.': 'भुट्टों को पौधे पर ही सूखने दें। छिलके सूखने पर कटाई करें।', 'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'पौधों को सहारा दें, निराई करें और ऊपर से खाद डालें। अर्ली ब्लाइट रोग और सफेद मक्खी की जाँच करें।', 'Top-dress nitrogen at squaring; scout for bollworm.': 'टिंडे बनने की अवस्था में नाइट्रोजन की ऊपरी खुराक डालें और बॉलवर्म कीट की जाँच करें।', 'Irrigate at flowering and boll formation; avoid waterlogging.': 'फूल आने और टिंडे बनने की अवस्था में सिंचाई करें। खेत में पानी जमा न होने दें।', 'Stop irrigation; pick bolls when fully open and dry.': 'सिंचाई बंद करें। टिंडे पूरी तरह खुलने और सूखने पर कपास चुनें।', 'Plant setts in moist soil, irrigate lightly and gap-fill.': 'नम मिट्टी में गन्ने के टुकड़े लगाएँ, हल्की सिंचाई करें और खाली जगहों पर पौधे लगाएँ।', 'Weed, earth up, top-dress nitrogen and mulch with trash.': 'निराई करें, पौधों के पास मिट्टी चढ़ाएँ, नाइट्रोजन की ऊपरी खुराक डालें और सूखी पत्तियों से मल्चिंग करें।', 'Irrigate every 7-10 days in hot weather; prop canes against lodging; scout for borers.': 'गर्म मौसम में हर 7–10 दिन में सिंचाई करें। गन्ने को गिरने से बचाने के लिए सहारा दें और छेदक कीटों की जाँच करें।', 'Withhold water 3-4 weeks before harvest to raise sugar; harvest at maturity.': 'शर्करा की मात्रा बढ़ाने के लिए कटाई से 3–4 सप्ताह पहले सिंचाई रोक दें। फसल पकने पर कटाई करें।'}, 'kn': {'Transplant healthy seedlings, keep 2-3 cm water and apply basal fertilizer.': 'ಆರೋಗ್ಯಕರ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಿ, ಹೊಲದಲ್ಲಿ 2–3 ಸೆಂ.ಮೀ. ನೀರು ಇರಿಸಿ ಮತ್ತು ನಾಟಿ ಸಮಯದಲ್ಲಿ ಮೂಲ ಗೊಬ್ಬರ ಹಾಕಿ.', 'Weed at 20-25 days, top-dress urea at tillering and scout for stem borer.': '20–25 ದಿನಗಳಲ್ಲಿ ಕಳೆ ತೆಗೆಯಿರಿ, ತೆಂಡೆ ಒಡೆಯುವ ಹಂತದಲ್ಲಿ ಯೂರಿಯಾವನ್ನು ಮೇಲ್ಗೊಬ್ಬರವಾಗಿ ಹಾಕಿ ಮತ್ತು ಕಾಂಡ ಕೊರೆಯುವ ಕೀಟವನ್ನು ಗಮನಿಸಿ.', 'Keep about 5 cm water at flowering; watch for blast and planthopper.': 'ಹೂ ಬಿಡುವ ಹಂತದಲ್ಲಿ ಸುಮಾರು 5 ಸೆಂ.ಮೀ. ನೀರು ಇರಿಸಿ; ಬ್ಲಾಸ್ಟ್ ರೋಗ ಮತ್ತು ಪ್ಲಾಂಟ್ ಹಾಪರ್ ಕೀಟವನ್ನು ಗಮನಿಸಿ.', 'Drain the field about 10 days before harvest; harvest at 80-85% golden grains.': 'ಕೊಯ್ಲಿಗೆ ಸುಮಾರು 10 ದಿನ ಮೊದಲು ಹೊಲದ ನೀರನ್ನು ಹೊರಹಾಕಿ; 80–85% ಕಾಳುಗಳು ಚಿನ್ನದ ಬಣ್ಣವಾದಾಗ ಕೊಯ್ಲು ಮಾಡಿ.', 'Sow at the right depth; give the first irrigation at 20-25 days (crown root stage).': 'ಸರಿಯಾದ ಆಳದಲ್ಲಿ ಬಿತ್ತನೆ ಮಾಡಿ; 20–25 ದಿನಗಳಲ್ಲಿ (ಕಿರೀಟ ಬೇರು ಹಂತದಲ್ಲಿ) ಮೊದಲ ನೀರಾವರಿ ನೀಡಿ.', 'Weed at 30-35 days, top-dress urea and irrigate at tillering.': '30–35 ದಿನಗಳಲ್ಲಿ ಕಳೆ ತೆಗೆಯಿರಿ, ಯೂರಿಯಾ ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ ಮತ್ತು ತೆಂಡೆ ಒಡೆಯುವ ಹಂತದಲ್ಲಿ ನೀರಾವರಿ ಮಾಡಿ.', 'Irrigate at flowering and grain filling; scout for rust.': 'ಹೂ ಬಿಡುವ ಮತ್ತು ಕಾಳು ತುಂಬುವ ಹಂತದಲ್ಲಿ ನೀರಾವರಿ ಮಾಡಿ; ತುಕ್ಕು ರೋಗದ ಲಕ್ಷಣಗಳನ್ನು ಗಮನಿಸಿ.', 'Stop irrigation as grains harden; harvest when grains are hard and dry.': 'ಕಾಳುಗಳು ಗಟ್ಟಿಯಾಗಲು ಆರಂಭಿಸಿದಾಗ ನೀರಾವರಿ ನಿಲ್ಲಿಸಿ; ಕಾಳುಗಳು ಗಟ್ಟಿಯಾಗಿ ಒಣಗಿದಾಗ ಕೊಯ್ಲು ಮಾಡಿ.', 'Thin plants, gap-fill and weed early.': 'ಸಸಿಗಳ ಸಂಖ್ಯೆಯನ್ನು ಸರಿಪಡಿಸಿ, ಖಾಲಿ ಜಾಗಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನೆಡಿ ಮತ್ತು ಆರಂಭದಲ್ಲೇ ಕಳೆ ತೆಗೆಯಿರಿ.', 'Earth up and top-dress urea at knee height; scout for fall armyworm.': 'ಸಸಿಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣು ಏರಿಸಿ, ಮೊಣಕಾಲಿನ ಎತ್ತರದಲ್ಲಿ ಯೂರಿಯಾ ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ; ಫಾಲ್ ಆರ್ಮಿವರ್ಮ್ ಕೀಟವನ್ನು ಗಮನಿಸಿ.', 'Never let soil dry at tasseling and silking; irrigate on time.': 'ಗಂಡು ಹೂ ಮತ್ತು ರೇಷ್ಮೆ ಹೊರಬರುವ ಹಂತದಲ್ಲಿ ಮಣ್ಣು ಒಣಗದಂತೆ ನೋಡಿ; ಸಮಯಕ್ಕೆ ನೀರಾವರಿ ಮಾಡಿ.', 'Let cobs dry on the plant; harvest when husks turn dry.': 'ತೆನೆಗಳನ್ನು ಗಿಡದಲ್ಲೇ ಒಣಗಲು ಬಿಡಿ; ಮೇಲಿನ ಹೊದಿಕೆ ಒಣಗಿದಾಗ ಕೊಯ್ಲು ಮಾಡಿ.', 'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'ಗಿಡಗಳಿಗೆ ಆಧಾರ ನೀಡಿ, ಕಳೆ ತೆಗೆಯಿರಿ ಮತ್ತು ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ. ಆರಂಭಿಕ ಅಂಗಮಾರಿ ರೋಗ ಹಾಗೂ ಬಿಳಿ ನೊಣಗಳನ್ನು ಗಮನಿಸಿ.', 'Top-dress nitrogen at squaring; scout for bollworm.': 'ಚೌಕ ಮೊಗ್ಗು ಹಂತದಲ್ಲಿ ಸಾರಜನಕ ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ; ಬೋಲ್\u200cವರ್ಮ್ ಕೀಟವನ್ನು ಗಮನಿಸಿ.', 'Irrigate at flowering and boll formation; avoid waterlogging.': 'ಹೂ ಬಿಡುವ ಮತ್ತು ಹತ್ತಿ ಕಾಯಿ ರೂಪುಗೊಳ್ಳುವ ಹಂತದಲ್ಲಿ ನೀರಾವರಿ ಮಾಡಿ; ನೀರು ನಿಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಿ.', 'Stop irrigation; pick bolls when fully open and dry.': 'ನೀರಾವರಿ ನಿಲ್ಲಿಸಿ; ಕಾಯಿಗಳು ಸಂಪೂರ್ಣವಾಗಿ ತೆರೆದು ಒಣಗಿದಾಗ ಹತ್ತಿ ಕಾಯಿ ಕೀಳಿರಿ.', 'Plant setts in moist soil, irrigate lightly and gap-fill.': 'ತೇವವಿರುವ ಮಣ್ಣಿನಲ್ಲಿ ಕಬ್ಬಿನ ತುಂಡುಗಳನ್ನು ನೆಡಿ, ಸ್ವಲ್ಪ ನೀರು ಹಾಕಿ ಮತ್ತು ಖಾಲಿ ಜಾಗಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನೆಡಿ.', 'Weed, earth up, top-dress nitrogen and mulch with trash.': 'ಕಳೆ ತೆಗೆಯಿರಿ, ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣು ಏರಿಸಿ, ಸಾರಜನಕ ಮೇಲ್ಗೊಬ್ಬರ ಹಾಕಿ ಮತ್ತು ಒಣ ಎಲೆಗಳಿಂದ ಮಲ್ಚಿಂಗ್ ಮಾಡಿ.', 'Irrigate every 7-10 days in hot weather; prop canes against lodging; scout for borers.': 'ಬಿಸಿ ವಾತಾವರಣದಲ್ಲಿ ಪ್ರತಿ 7–10 ದಿನಕ್ಕೊಮ್ಮೆ ನೀರಾವರಿ ಮಾಡಿ; ಕಬ್ಬು ಬೀಳದಂತೆ ಆಧಾರ ನೀಡಿ ಮತ್ತು ಕೊರೆಯುವ ಕೀಟಗಳನ್ನು ಗಮನಿಸಿ.', 'Withhold water 3-4 weeks before harvest to raise sugar; harvest at maturity.': 'ಸಕ್ಕರೆ ಅಂಶ ಹೆಚ್ಚಿಸಲು ಕೊಯ್ಲಿಗೆ 3–4 ವಾರ ಮೊದಲು ನೀರು ನಿಲ್ಲಿಸಿ; ಬೆಳೆ ಪಕ್ವವಾದಾಗ ಕೊಯ್ಲು ಮಾಡಿ.'}, 'te': {'Transplant healthy seedlings, keep 2-3 cm water and apply basal fertilizer.': 'ఆరోగ్యకరమైన నారును నాటండి, పొలంలో 2–3 సెం.మీ. నీరు ఉంచండి మరియు నాటే సమయంలో ప్రాథమిక ఎరువు వేయండి.', 'Weed at 20-25 days, top-dress urea at tillering and scout for stem borer.': '20–25 రోజులకు కలుపు తీయండి, పిలకలు వచ్చే దశలో యూరియాను పై ఎరువుగా వేయండి మరియు కాండం తొలిచే పురుగును గమనించండి.', 'Keep about 5 cm water at flowering; watch for blast and planthopper.': 'పూత దశలో సుమారు 5 సెం.మీ. నీరు ఉంచండి; బ్లాస్ట్ తెగులు మరియు ప్లాంట్ హాపర్ పురుగులను గమనించండి.', 'Drain the field about 10 days before harvest; harvest at 80-85% golden grains.': 'కోతకు సుమారు 10 రోజుల ముందు పొలంలోని నీటిని బయటకు పంపండి; 80–85% గింజలు బంగారు రంగులోకి మారినప్పుడు కోయండి.', 'Sow at the right depth; give the first irrigation at 20-25 days (crown root stage).': 'సరైన లోతులో విత్తండి; 20–25 రోజులకు (క్రౌన్ రూట్ దశలో) మొదటి తడిని ఇవ్వండి.', 'Weed at 30-35 days, top-dress urea and irrigate at tillering.': '30–35 రోజులకు కలుపు తీయండి, యూరియాను పై ఎరువుగా వేయండి మరియు పిలకలు వచ్చే దశలో నీరు పెట్టండి.', 'Irrigate at flowering and grain filling; scout for rust.': 'పూత మరియు గింజ నిండే దశల్లో నీరు పెట్టండి; తుప్పు తెగులు లక్షణాలను గమనించండి.', 'Stop irrigation as grains harden; harvest when grains are hard and dry.': 'గింజలు గట్టిపడటం ప్రారంభమైనప్పుడు నీరు పెట్టడం ఆపండి; గింజలు గట్టిగా, పొడిగా ఉన్నప్పుడు కోయండి.', 'Thin plants, gap-fill and weed early.': 'మొక్కల సంఖ్యను సరిచేయండి, ఖాళీ ప్రదేశాల్లో మొక్కలు నాటండి మరియు మొదట్లోనే కలుపు తీయండి.', 'Earth up and top-dress urea at knee height; scout for fall armyworm.': 'మొక్కల మొదళ్లకు మట్టిని ఎత్తండి, మోకాలి ఎత్తులో యూరియాను పై ఎరువుగా వేయండి; ఫాల్ ఆర్మీవార్మ్ పురుగును గమనించండి.', 'Never let soil dry at tasseling and silking; irrigate on time.': 'కంకి మరియు పట్టు వచ్చే దశలో నేల ఎండిపోనివ్వకండి; సమయానికి నీరు పెట్టండి.', 'Let cobs dry on the plant; harvest when husks turn dry.': 'కంకులు మొక్కపైనే ఎండనివ్వండి; పొత్తులు ఎండినప్పుడు కోయండి.', 'Stake plants, weed, top-dress; scout for early blight and whitefly.': 'మొక్కలకు కర్రలతో ఆధారం ఇవ్వండి, కలుపు తీయండి, పై ఎరువు వేయండి. ఎర్లీ బ్లైట్ తెగులు మరియు తెల్లదోమలను గమనించండి.', 'Top-dress nitrogen at squaring; scout for bollworm.': 'చతురస్ర మొగ్గ దశలో నత్రజనిని పై ఎరువుగా వేయండి; కాయ తొలిచే పురుగును గమనించండి.', 'Irrigate at flowering and boll formation; avoid waterlogging.': 'పూత మరియు కాయలు ఏర్పడే దశల్లో నీరు పెట్టండి; పొలంలో నీరు నిల్వ ఉండనివ్వకండి.', 'Stop irrigation; pick bolls when fully open and dry.': 'నీరు పెట్టడం ఆపండి; కాయలు పూర్తిగా విచ్చి ఎండినప్పుడు పత్తి ఏరండి.', 'Plant setts in moist soil, irrigate lightly and gap-fill.': 'తేమ ఉన్న నేలలో చెరకు ముక్కలు నాటండి, కొద్దిగా నీరు పెట్టండి మరియు ఖాళీ ప్రదేశాల్లో మొక్కలు నాటండి.', 'Weed, earth up, top-dress nitrogen and mulch with trash.': 'కలుపు తీయండి, మొక్కల మొదళ్లకు మట్టిని ఎత్తండి, నత్రజని పై ఎరువు వేయండి మరియు ఎండిన ఆకులతో మల్చింగ్ చేయండి.', 'Irrigate every 7-10 days in hot weather; prop canes against lodging; scout for borers.': 'వేడి వాతావరణంలో ప్రతి 7–10 రోజులకు నీరు పెట్టండి; చెరకు పడిపోకుండా ఆధారం ఇవ్వండి మరియు తొలిచే పురుగులను గమనించండి.', 'Withhold water 3-4 weeks before harvest to raise sugar; harvest at maturity.': 'చక్కెర శాతం పెరగడానికి కోతకు 3–4 వారాల ముందు నీరు పెట్టడం ఆపండి; పంట పక్వానికి వచ్చినప్పుడు కోయండి.'}}
for _lang, _items in _STAGE_ACTION_TRANSLATIONS.items():
    ADVICE_PHRASES.setdefault(_lang, {}).update(_items)
